begin;
create temp table assertions(label text);
grant select,insert on assertions to authenticated;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAILED: %',label;end if;insert into assertions values(label);end$$;
create temp table content_fixture(packet jsonb,pages jsonb,binding jsonb,result jsonb);
insert into content_fixture values (__BOARD_PACKET__::jsonb,__BOARD_PAGES__::jsonb,'{"presentationId":"15000000-0000-4000-8000-000000000007","channelEpoch":"15000000-0000-4000-8000-000000000008"}',null);
grant select,update on content_fixture to authenticated;
insert into auth.users(id,email,is_anonymous) values('15000000-0000-4000-8000-000000000001','content-a@qa.invalid',false),('15000000-0000-4000-8000-000000000002','content-b@qa.invalid',false),('15000000-0000-4000-8000-000000000003',null,true),('15000000-0000-4000-8000-000000000004',null,true);
insert into public.classes(id,owner_id,label,grade,student_count,runtime_mode) values('15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001','7P',7,16,'demo');
insert into pn_private.presentation_sessions(id,class_id,owner_id) values('15000000-0000-4000-8000-000000000006','15000000-0000-4000-8000-000000000005','15000000-0000-4000-8000-000000000001');
insert into pn_private.presentations(id,session_id,owner_id,board_id,channel_epoch,public_state) select '15000000-0000-4000-8000-000000000007','15000000-0000-4000-8000-000000000006','15000000-0000-4000-8000-000000000001','15000000-0000-4000-8000-000000000003','15000000-0000-4000-8000-000000000008',pages->0 from content_fixture;
select pg_temp.ok(pn_private.valid_board_packet(packet),'actual generated package passes SQL allowlist') from content_fixture;
select pg_temp.ok(not pn_private.valid_board_packet(jsonb_set(packet,'{content,names}','[]')),'persistent name field denied') from content_fixture;
select pg_temp.ok(not pn_private.valid_board_packet(jsonb_set(packet,'{content,content,assessment,0,answerKey}','"A"')),'assessment key denied') from content_fixture;
select pg_temp.ok(not pn_private.valid_board_packet(jsonb_set(packet,'{plan,groups,0,activityId}',packet#>'{plan,id}')),'unknown activity reference denied') from content_fixture;
select pg_temp.ok(not pn_private.valid_board_packet(jsonb_set(packet,'{content,models,0,questionId}',packet#>'{content,content,assessment,0,id}')),'assessment model answer path denied') from content_fixture;
select pg_temp.ok((select bool_and(pn_private.valid_public_state(v)) from jsonb_array_elements(pages) v),'all cached navigation projections pass database contract') from content_fixture;
select pg_temp.ok(not has_table_privilege('authenticated','pn_private.board_packages','SELECT'),'content table private');
select pg_temp.ok((select relrowsecurity from pg_class where oid='pn_private.board_packages'::regclass),'RLS enabled');
select pg_temp.ok(not has_function_privilege('authenticated','public.presentation_action_before_content(text,jsonb)','EXECUTE'),'no legacy ACK bypass');
select pg_temp.ok(not has_function_privilege('authenticated','public.remote_tool_action_before_content(text,jsonb)','EXECUTE'),'no legacy remote bypass');
set local role authenticated;
set local request.jwt.claims='{"sub":"15000000-0000-4000-8000-000000000002","is_anonymous":false}';
select pg_temp.ok((select public.board_content_action('write',binding||jsonb_build_object('action','write','packet',packet))->>'error'='FORBIDDEN' from content_fixture),'other teacher cannot write');
select pg_temp.ok((select public.board_content_action('read',binding||'{"action":"read"}')->>'error'='FORBIDDEN' from content_fixture),'other teacher cannot read');
set local request.jwt.claims='{"sub":"15000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok((select public.board_content_action('write',binding||jsonb_build_object('action','write','packet',packet))->>'error'='FORBIDDEN' from content_fixture),'board cannot author packet');
set local request.jwt.claims='{"sub":"15000000-0000-4000-8000-000000000001","is_anonymous":false}';
update content_fixture set result=public.board_content_action('write',binding||jsonb_build_object('action','write','packet',packet));
select pg_temp.ok(result->>'packetVersion'='1' and result->'packet'='null'::jsonb,'owner uploads but no redundant private packet echo') from content_fixture;
select pg_temp.ok((select public.board_content_action('write',binding||jsonb_build_object('action','write','packet',jsonb_set(packet,'{content,lesson,prompt}','"Changed"')))->>'error'='CONFLICT' from content_fixture),'same version content immutable');
select pg_temp.ok((select public.board_content_action('read',binding||'{"action":"read","name":"CANARY"}')->>'error'='INVALID_INPUT' from content_fixture),'unknown request fields rejected');
set local request.jwt.claims='{"sub":"15000000-0000-4000-8000-000000000004","is_anonymous":true}';
select pg_temp.ok((select public.board_content_action('read',binding||'{"action":"read"}')->>'error'='FORBIDDEN' from content_fixture),'unpaired board cannot read');
set local request.jwt.claims='{"sub":"15000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok((select public.board_content_action('read',binding||'{"action":"read"}')->'packet'=packet from content_fixture),'paired board receives public packet');
select pg_temp.ok((select public.board_content_action('read',binding||'{"action":"read","knownVersion":1}')->'packet'='null'::jsonb from content_fixture),'unchanged content not repeatedly transferred');
select pg_temp.ok((select public.board_content_action('cached',binding||jsonb_build_object('action','cached','packageId',packet#>'{content,content,id}','revision',packet#>'{content,content,revision}'))->'cached'='true' from content_fixture),'durable cache receipt');
select pg_temp.ok((select public.board_content_action('uncache',binding||jsonb_build_object('action','uncache','packageId',packet#>'{content,content,id}','revision',packet#>'{content,content,revision}'))->'cached'='false' from content_fixture),'clearing cache clears receipt');
select pg_temp.ok((select public.board_content_action('propose',binding||jsonb_build_object('action','propose','packetVersion',1,'payload',(pages->1)||'{"name":"CANARY"}'))->>'error'='INVALID_INPUT' from content_fixture),'local takeover cannot add identity');
select pg_temp.ok((select public.board_content_action('propose',binding||jsonb_build_object('action','propose','packetVersion',1,'payload',(select v from jsonb_array_elements(pages) v where v->>'mode'='station' and v?'tool' limit 1)||'{"guidance":{"hint":3,"reveal":true}}'))->>'error'='INVALID_INPUT' from content_fixture),'board cannot force practice reveal');
update content_fixture set result=public.board_content_action('propose',binding||jsonb_build_object('action','propose','packetVersion',1,'payload',pages->1));
select pg_temp.ok(result->'proposal'=pages->1,'local navigation reported for teacher choice') from content_fixture;
select pg_temp.ok((select public.remote_tool_action('read',binding||jsonb_build_object('action','read','taskEpoch',pages#>'{0,taskEpoch}'))->>'error'='CONFLICT' from content_fixture),'remote disabled during local takeover');
select pg_temp.ok((select public.presentation_action('ack',binding||'{"action":"ack","appliedRevision":1,"commandId":"15000000-0000-4000-8000-000000000030"}')->>'error'='CONFLICT' from content_fixture),'old heartbeat cannot ACK local display as HP display');
select pg_temp.ok((select public.board_content_action('resolve',binding||jsonb_build_object('action','resolve','proposalEpoch',pages#>'{1,taskEpoch}','baseRevision',1,'commandId','15000000-0000-4000-8000-000000000020','taskEpoch','15000000-0000-4000-8000-000000000021','choice','board'))->>'error'='FORBIDDEN' from content_fixture),'board cannot resolve own takeover');
set local request.jwt.claims='{"sub":"15000000-0000-4000-8000-000000000001","is_anonymous":false}';
select pg_temp.ok((select public.board_content_action('read',binding||'{"action":"read"}')->'proposal'=pages->1 from content_fixture),'owner sees reconciliation proposal');
update content_fixture set result=public.board_content_action('write',binding||jsonb_build_object('action','write','packet',jsonb_set(packet,'{plan,groups,0,activityId}',packet#>'{plan,groups,1,activityId}')));
select pg_temp.ok(result->'proposal'=pages->1 and result->>'proposalStale'='true' and result->>'packetVersion'='2','run plan update retains takeover and marks it stale') from content_fixture;
select pg_temp.ok((select public.board_content_action('resolve',binding||jsonb_build_object('action','resolve','proposalEpoch',pages#>'{1,taskEpoch}','baseRevision',1,'commandId','15000000-0000-4000-8000-000000000020','taskEpoch','15000000-0000-4000-8000-000000000021','choice','board'))->>'error'='CONFLICT' from content_fixture),'cannot adopt stale run plan');
set local request.jwt.claims='{"sub":"15000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok((select public.board_content_action('propose',binding||jsonb_build_object('action','propose','packetVersion',1,'payload',pages->1))->>'error'='CONFLICT' from content_fixture),'offline stale plan cannot be proposed as current');
select pg_temp.ok((select public.board_content_action('propose',binding||jsonb_build_object('action','propose','packetVersion',2,'payload',pages->1))->>'proposalStale'='false' from content_fixture),'reselected current plan clears stale flag');
set local request.jwt.claims='{"sub":"15000000-0000-4000-8000-000000000001","is_anonymous":false}';
select pg_temp.ok((select public.board_content_action('resolve',binding||jsonb_build_object('action','resolve','proposalEpoch','15000000-0000-4000-8000-000000000099','baseRevision',1,'commandId','15000000-0000-4000-8000-000000000020','taskEpoch','15000000-0000-4000-8000-000000000021','choice','board'))->>'error'='CONFLICT' from content_fixture),'stale takeover choice rejected');
update content_fixture set result=public.board_content_action('resolve',binding||jsonb_build_object('action','resolve','proposalEpoch',pages#>'{1,taskEpoch}','baseRevision',1,'commandId','15000000-0000-4000-8000-000000000020','taskEpoch','15000000-0000-4000-8000-000000000021','choice','board'));
select pg_temp.ok(result#>>'{snapshot,envelope,payload,mode}'='check' and result#>>'{resolution,revision}'='2' and result->'proposal'='null'::jsonb,'explicit board choice updates canonical state once') from content_fixture;
reset role;
update pn_private.presentations set revoked=true where id='15000000-0000-4000-8000-000000000007';
set local role authenticated;
set local request.jwt.claims='{"sub":"15000000-0000-4000-8000-000000000003","is_anonymous":true}';
select pg_temp.ok((select public.board_content_action('read',binding||'{"action":"read"}')->>'error'='FORBIDDEN' from content_fixture),'revoke cuts content access');
select 'PASS '||count(*)||' board content SQL assertions' from assertions;
rollback;
